class Shape:
    def area(self):
        return 0


class Square(Shape):
    def __init__(self, side):
        self.side = side

    def area(self):
        return self.side ** 2


class Broken(Shape):
    def area(self):
        raise NotImplementedError


total = 0
for shape in [Square(2), Shape(), Broken(), Square(3)]:
    try:
        total += shape.area()
    except NotImplementedError:
        print("пропущена фигура")
print(total)
